import {normalizeFeed,filtered,amapLink,toWgs84,mergeFeeds,articleLink} from './food-core.js';
import {mapStyle,createPin} from './map-appearance.js';
import {loadAmap} from './amap-loader.js';
import {translate as t,locale} from './i18n.js';
const $=id=>document.getElementById(id);const state={rows:[],map:null,markers:[],active:null,engine:null,busy:false,satellite:null,roads:null,traffic:null,info:null};
function element(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
function link(text,url){const node=element('a',text);node.href=url;node.target='_blank';node.rel='noopener noreferrer';return node;}
function matches(){return filtered(state.rows,$('search').value,$('city').value,$('category').value);}
function popup(p){const box=element('div',undefined,'atlas-popup');box.append(element('h3',p.name),element('p',p.city+' · '+t(p.category)),element('p',p.address||t('Check the original venue listing.')),link(t('Open in Amap ↗'),amapLink(p)));const original=articleLink(p);if(original)box.append(element('br'),link(t('Original recommendation ↗'),original));return box;}
function highlight(){for(const marker of state.markers){const active=marker.venueId===state.active;marker.pin.setAttribute('aria-pressed',String(active));if(state.engine==='amap')marker.setzIndex(active?200:100);else marker.setZIndexOffset(active?200:0);}}
function select(p){state.active=p.id;document.querySelectorAll('.venue-card').forEach(c=>c.classList.toggle('selected',c.dataset.id===p.id));highlight();if(state.map){if(state.engine==='amap'){state.map.setZoomAndCenter(15,[p.lng,p.lat]);state.info?.close();state.info=new AMap.InfoWindow({content:popup(p),offset:new AMap.Pixel(0,-48)});state.info.open(state.map,[p.lng,p.lat]);}else{state.map.setView(toWgs84(p.lng,p.lat),15);state.markers.find(m=>m.venueId===p.id)?.openPopup();}}else{$('map-status').textContent=t('Selected: {name}. Load the map to see its marker.',{name:p.name});}}
function markers(){if(!state.map)return;state.info?.close();state.info=null;state.markers.forEach(m=>state.engine==='amap'?m.setMap(null):m.remove());state.markers=[];for(const p of matches()){const pin=createPin(document,p,p.mapNumber,()=>select(p));const marker=state.engine==='amap'?new AMap.Marker({position:[p.lng,p.lat],title:p.name,content:pin,anchor:'bottom-center',map:state.map}):L.marker(toWgs84(p.lng,p.lat),{icon:L.divIcon({html:pin,className:'atlas-div-icon',iconSize:[42,49],iconAnchor:[21,49],popupAnchor:[0,-43]})}).addTo(state.map).bindPopup(popup(p));marker.venueId=p.id;marker.pin=pin;marker.on('click',()=>select(p));state.markers.push(marker);}highlight();}
let lastMapStyle=null;
function syncTheme(){if(state.engine==='amap'&&state.map){const style=mapStyle(document.body.classList.contains('dark'));if(style!==lastMapStyle){state.map.setMapStyle(style);lastMapStyle=style;}}}
new MutationObserver(syncTheme).observe(document.body,{attributes:true,attributeFilter:['class']});
function fit(){if(!state.map||!state.markers.length)return;if(state.engine==='amap')state.map.setFitView(state.markers,false,[40,40,40,40],13);else state.map.fitBounds(L.featureGroup(state.markers).getBounds(),{padding:[40,40],maxZoom:13});}
function layers(){if(state.engine!=='amap'||!state.map)return;for(const layer of [state.satellite,state.roads,state.traffic])if(layer)state.map.remove(layer);if($('map-layer').value==='satellite'){state.satellite??=new AMap.TileLayer.Satellite();state.roads??=new AMap.TileLayer.RoadNet();state.map.add([state.satellite,state.roads]);}if($('map-traffic').checked){state.traffic??=new AMap.TileLayer.Traffic({autoRefresh:false});state.map.add(state.traffic);}}
function render(){const rows=matches();$('result-count').textContent=t('Places to explore: {count}',{count:rows.length});$('results').replaceChildren();if(!rows.length)$('results').append(element('p',t('No matching places. Try another city or reset the filters.'),'empty-state'));for(const p of rows){const card=element('article',undefined,'venue-card');card.dataset.id=p.id;card.classList.toggle('selected',p.id===state.active);const top=element('div',undefined,'venue-top');top.append(element('span',String(p.mapNumber).padStart(2,'0')+' / '+p.city),element('span',t(p.category)));const actions=element('div',undefined,'venue-actions');const button=element('button',t('Show on map'));button.type='button';button.addEventListener('click',()=>select(p));actions.append(button,link(t('Amap ↗'),amapLink(p)));const original=articleLink(p);if(original)actions.append(link(t('Original ↗'),original));card.append(top,element('h2',p.name),element('p',p.address||t('Address details in the original listing.')),actions);$('results').append(card);}markers();}
async function loadMap(){
 if(state.busy)return;state.busy=true;const engine=$('map-provider').value;const button=$('load-map');button.disabled=true;button.textContent=t('Loading the map…');
 try{
  if(engine==='amap')await loadAmap();else if(!window.L)await new Promise((resolve,reject)=>{const script=document.createElement('script');const timer=setTimeout(()=>{script.remove();reject(new Error('Map library timeout'));},15000);script.src='/assets/vendor/leaflet.js';script.onload=()=>{clearTimeout(timer);resolve();};script.onerror=()=>{clearTimeout(timer);reject(new Error('Map library unavailable'));};document.head.append(script);});
  if(state.map){state.engine==='amap'?state.map.destroy():state.map.remove();state.map=null;}state.engine=engine;state.markers=[];state.satellite=state.roads=state.traffic=null;state.info=null;lastMapStyle=null;$('map-navigation').hidden=true;
  $('map-canvas').replaceChildren();
  if(engine==='amap'){state.map=new AMap.Map('map-canvas',{zoom:4,center:[108.9,34.3],viewMode:'2D',mapStyle:mapStyle(document.body.classList.contains('dark')),lang:locale==='en'?'en':'zh_cn'});layers();$('map-status').textContent=t('Amap · original GCJ-02 coordinates');}
  else{state.map=L.map('map-canvas',{scrollWheelZoom:false,zoomControl:false}).setView([34.3,108.9],4);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> '+t('contributors'),updateWhenIdle:true,keepBuffer:1}).addTo(state.map).on('tileerror',()=>{$('map-status').textContent=t('Some map tiles are unavailable; the venue list and Amap links still work.');});
  $('map-status').textContent=t('Approximate WGS84 markers · source coordinates remain GCJ-02');}
  markers();fit();$('map-navigation').hidden=false;$('map-placeholder').hidden=true;$('fit-map').hidden=false;button.textContent=t('Open interactive map ↗');
  if(state.active){const p=state.rows.find(p=>p.id===state.active);if(p)select(p);}
 }catch(error){$('map-status').textContent=t(error.message==='configuration'?'Amap is not configured on the server yet. Use OpenStreetMap or the venue links.':'The map could not load. The venue list and Amap links remain available.');button.textContent=t('Try loading the map again');}finally{state.busy=false;button.disabled=false;}
}
async function load(){try{const feeds=await Promise.allSettled(['/food-map/index.json','/data/food.json'].map(async url=>{const response=await fetch(url,{signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('Collection unavailable');const data=await response.json();normalizeFeed(data);return data;}));if(feeds.every(p=>p.status==='rejected'))throw new Error('Collections unavailable');const empty={schemaVersion:1,coordinateSystem:'GCJ-02',spots:[]};const own=feeds[0].status==='fulfilled'?feeds[0].value:empty;const data=feeds[1].status==='fulfilled'?feeds[1].value:empty;state.rows=mergeFeeds(own,data);state.rows.forEach((p,index)=>{p.mapNumber=index+1;});$('total-count').textContent=state.rows.length;const date=new Date(data.retrievedAt||own.generatedAt);$('updated').textContent=Number.isNaN(date.valueOf())?t('Public source'):t('Source changed {date}',{date:date.toLocaleDateString({zh:'zh-CN',en:'en-GB',ru:'ru-RU',ja:'ja-JP'}[locale],{day:'numeric',month:'short',year:'numeric'})});for(const [id,values] of [['city',[...new Set(state.rows.map(p=>p.city))].sort()],['category',[...new Set(state.rows.map(p=>p.category))].sort()]])for(const value of values){const option=element('option',id==='category'?t(value):value);option.value=value;$(id).append(option);}render();}catch(error){$('result-count').textContent=t('Collection temporarily unavailable');$('updated').textContent=t('No private or fabricated data was substituted.');$('results').replaceChildren(element('p',t('The public collection could not be loaded. Please return later or visit the original source.'),'empty-state'));}}
$('map-zoom-in').addEventListener('click',()=>state.map?.zoomIn());$('map-zoom-out').addEventListener('click',()=>state.map?.zoomOut());
$('search').addEventListener('input',render);$('city').addEventListener('change',()=>{render();fit();});$('category').addEventListener('change',()=>{render();fit();});$('reset').addEventListener('click',()=>{$('search').value='';$('city').value='';$('category').value='';render();fit();});$('load-map').addEventListener('click',loadMap);$('fit-map').addEventListener('click',fit);$('map-layer').addEventListener('change',layers);$('map-traffic').addEventListener('change',layers);$('map-provider').addEventListener('change',()=>{$('map-layer').disabled=$('map-traffic').disabled=$('map-provider').value!=='amap';if(state.map)loadMap();});load();
